package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetMemberUseCase;
import com.example.lending.application.port.in.ListMemberLoansUseCase;
import com.example.lending.application.port.in.ListMemberLoansUseCase.ListMemberLoansQuery;
import com.example.lending.application.port.in.RegisterMemberUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase.RegisterMemberCommand;
import com.example.lending.domain.Member;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.UUID;

@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final ListMemberLoansUseCase listMemberLoansUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            ListMemberLoansUseCase listMemberLoansUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.listMemberLoansUseCase = listMemberLoansUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        Member member = registerMemberUseCase.registerMember(new RegisterMemberCommand(request.memberId(), request.name()));
        return MemberResponse.from(member);
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    // 반납하지 않은 대출 목록. page 는 0부터 시작한다
    @GetMapping("/{memberId}/loans")
    public MemberLoansResponse listActiveLoans(@PathVariable UUID memberId,
                                               @RequestParam(defaultValue = "0") int page,
                                               @RequestParam(defaultValue = "20") int size) {
        var result = listMemberLoansUseCase.listActiveLoans(new ListMemberLoansQuery(memberId, page, size));
        return MemberLoansResponse.of(result, page, size);
    }
}
package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.ListMemberLoansUseCase.ActiveLoan;
import com.example.lending.application.port.in.ListMemberLoansUseCase.ActiveLoanPage;

import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

public record MemberLoansResponse(List<LoanItem> items, int page, int size, long totalCount) {

    static MemberLoansResponse of(ActiveLoanPage result, int page, int size) {
        List<LoanItem> items = result.items().stream().map(LoanItem::from).toList();
        return new MemberLoansResponse(items, page, size, result.totalCount());
    }

    public record LoanItem(UUID loanId, UUID bookId, String title, LocalDate loanedAt, LocalDate dueAt) {

        static LoanItem from(ActiveLoan loan) {
            return new LoanItem(loan.loanId(), loan.bookId(), loan.title(), loan.loanedAt(), loan.dueAt());
        }
    }
}
package com.example.lending.application.port.in;

import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

public interface ListMemberLoansUseCase {

    ActiveLoanPage listActiveLoans(ListMemberLoansQuery query);

    record ListMemberLoansQuery(UUID memberId, int page, int size) {

        public static final int MAX_SIZE = 100;

        public ListMemberLoansQuery {
            if (memberId == null) {
                throw new IllegalArgumentException("memberId is required");
            }
            if (page < 0) {
                throw new IllegalArgumentException("page must not be negative");
            }
            if (size < 1 || size > MAX_SIZE) {
                throw new IllegalArgumentException("size must be between 1 and " + MAX_SIZE);
            }
        }
    }

    // totalCount 는 페이지와 상관없이 반납하지 않은 대출 전체 건수다
    record ActiveLoanPage(List<ActiveLoan> items, long totalCount) {
    }

    record ActiveLoan(UUID loanId, UUID bookId, String title, LocalDate loanedAt, LocalDate dueAt) {
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.ListMemberLoansUseCase;
import com.example.lending.application.port.out.LoadActiveLoansPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class ListMemberLoansService implements ListMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadActiveLoansPort loadActiveLoansPort;

    public ListMemberLoansService(LoadMemberPort loadMemberPort, LoadActiveLoansPort loadActiveLoansPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadActiveLoansPort = loadActiveLoansPort;
    }

    @Override
    public ActiveLoanPage listActiveLoans(ListMemberLoansQuery query) {
        loadMemberPort.loadMember(query.memberId())
                .orElseThrow(() -> new MemberNotFoundException(query.memberId()));
        return loadActiveLoansPort.loadActiveLoans(query.memberId(), query.page(), query.size());
    }
}
