package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoanListIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void member_without_loans_gets_empty_list_with_zero_total() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items").isEmpty())
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void active_loans_are_sliced_by_page_and_size_with_total_count() throws Exception {
        String memberId = registerMember();
        loanOn(registerBook("Clean Code"), memberId, LocalDate.of(2026, 2, 1));
        loanOn(registerBook("Refactoring"), memberId, LocalDate.of(2026, 2, 2));
        loanOn(registerBook("Effective Java"), memberId, LocalDate.of(2026, 2, 3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-01"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-15"))
                .andExpect(jsonPath("$.items[1].title").value("Refactoring"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Effective Java"))
                .andExpect(jsonPath("$.totalCount").value(3));
    }

    @Test
    void returned_loans_are_excluded_from_the_list() throws Exception {
        String memberId = registerMember();
        String returnedLoanId = loanOn(registerBook("Clean Code"), memberId, LocalDate.of(2026, 2, 1));
        loanOn(registerBook("Refactoring"), memberId, LocalDate.of(2026, 2, 2));
        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId)).andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Refactoring"))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void other_members_loans_are_not_listed() throws Exception {
        String memberId = registerMember();
        String otherMemberId = registerMember();
        loanOn(registerBook("Clean Code"), otherMemberId, LocalDate.of(2026, 2, 1));

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items").isEmpty())
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void page_past_the_end_returns_empty_items_with_total_count() throws Exception {
        String memberId = registerMember();
        loanOn(registerBook("Clean Code"), memberId, LocalDate.of(2026, 2, 1));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "5").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items").isEmpty())
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void negative_page_returns_400() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void size_out_of_range_returns_400() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "101"))
                .andExpect(status().isBadRequest());
    }

    private String loanOn(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBodyOn(bookId, memberId, loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new BookBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    record LoanBodyOn(String bookId, String memberId, LocalDate loanedAt) {
    }

    record BookBody(String title) {
    }
}
