package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoanHistoryIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void member_without_loans_gets_empty_array() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void history_includes_returned_and_active_loans_newest_first() throws Exception {
        String memberId = registerMember();
        String oldest = loanOn(registerBook("Clean Code"), memberId, LocalDate.of(2026, 2, 1));
        loanOn(registerBook("Refactoring"), memberId, LocalDate.of(2026, 3, 10));
        String middle = loanOn(registerBook("Effective Java"), memberId, LocalDate.of(2026, 2, 20));
        mockMvc.perform(post("/loans/{loanId}/return", oldest).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-02-10\"}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/loans/{loanId}/return", middle).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-03-10\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(3))
                .andExpect(jsonPath("$[0].title").value("Refactoring"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[0].returnedAt").isEmpty())
                .andExpect(jsonPath("$[0].lateFee").isEmpty())
                .andExpect(jsonPath("$[1].title").value("Effective Java"))
                .andExpect(jsonPath("$[1].loanedAt").value("2026-02-20"))
                .andExpect(jsonPath("$[1].returnedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[1].lateFee").value(0))
                .andExpect(jsonPath("$[2].title").value("Clean Code"))
                .andExpect(jsonPath("$[2].loanedAt").value("2026-02-01"))
                .andExpect(jsonPath("$[2].returnedAt").value("2026-02-10"))
                .andExpect(jsonPath("$[2].lateFee").value(0));
    }

    @Test
    void late_return_shows_late_fee_in_history() throws Exception {
        String memberId = registerMember();
        // 대출일 2026-01-01 → 기한 2026-01-15, 2026-01-20 반납이면 5일 연체 = 500원
        String loanId = loanOn(registerBook("Clean Code"), memberId, LocalDate.of(2026, 1, 1));
        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-20\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].loanId").value(loanId))
                .andExpect(jsonPath("$[0].returnedAt").value("2026-01-20"))
                .andExpect(jsonPath("$[0].lateFee").value(500));
    }

    @Test
    void other_members_loans_are_not_in_history() throws Exception {
        String memberId = registerMember();
        String otherMemberId = registerMember();
        loanOn(registerBook("Clean Code"), otherMemberId, LocalDate.of(2026, 2, 1));

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans/history", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String loanOn(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBodyOn(bookId, memberId, loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new BookBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    record LoanBodyOn(String bookId, String memberId, LocalDate loanedAt) {
    }

    record BookBody(String title) {
    }
}
EOF
